message:
assert_equals: expected "@mixin --m1 {
  @result {
  color: red;
  & { --foo: bar; color: green; }
}
}" but got "@mixin --m1 {
  @result {
  color: red;
  & { --foo: bar; }
}
}"

assert_equals: expected "@mixin --m2 {
  @result {
  color: green;
}
}" but got "@mixin --m2 {
  @result {
  color: red;
}
}"
